	private List<BindingSet> select(String queryText, String document) {
		var query = connection.prepareTupleQuery(PROLOGUE + queryText);
		query.setBinding("doc", VF.createLiteral(document));
		List<BindingSet> rows = new ArrayList<>();
		try (var result = query.evaluate()) {
			while (result.hasNext()) {
				rows.add(result.next());
			}
		}
		return rows;
	}

	@ParameterizedTest
	@EnumSource(RdfParserBackend.class)
	void repeatedPreboundTupleResultsRetainEqualityConstraints(RdfParserBackend backend) {
		openRepository(backend);
		var query = connection.prepareTupleQuery(PROLOGUE
				+ "SELECT ?x ?o WHERE { ?doc parse:turtle (?x ?x ?o) }");
		query.setBinding("doc", VF.createLiteral("<urn:p> <urn:p> <urn:o> . <urn:s> <urn:p> <urn:ignored> ."));
		query.setBinding("x", VF.createIRI("urn:p"));
		try (var rows = query.evaluate()) {
			assertTrue(rows.hasNext());
			assertEquals(VF.createIRI("urn:o"), rows.next().getValue("o"));
			assertFalse(rows.hasNext());
		}
		var constants = select("SELECT ?o WHERE { ?doc parse:turtle (<urn:p> <urn:p> ?o) }",
				"<urn:p> <urn:p> <urn:o> . <urn:s> <urn:p> <urn:ignored> .");
		assertEquals(1, constants.size());
		assertEquals(VF.createIRI("urn:o"), constants.get(0).getValue("o"));
	}

