	@Test
	void rejectsInvalidTurtleStringEscapes() {
		var parser = new RdfDocumentParser(RdfParseOptions.DEFAULT);
		assertThrows(QueryEvaluationException.class, () -> parser.parse(
				VF.createLiteral("<urn:s> <urn:p> \"\\q\" ."), VF.createLiteral("text/turtle"), null));
	}

	@Test
	void stillAcceptsSyntacticallyValidIllTypedLiterals() {
		var parser = new RdfDocumentParser(RdfParseOptions.DEFAULT);
		var model = parser.parse(VF.createLiteral("""
				<urn:s> <urn:p> "not-an-integer"^^<http://www.w3.org/2001/XMLSchema#integer> .
				"""), VF.createLiteral("text/turtle"), null);
		assertEquals(1, model.size());
		assertEquals("not-an-integer", model.iterator().next().getObject().stringValue());
	}

