	@ParameterizedTest
	@EnumSource(RdfParserBackend.class)
	void tripleTermPatternsRespectNamedAndDefaultGraphs(RdfParserBackend backend) {
		openRepository(backend);
		String document = """
				VERSION "1.2"
				<urn:g> { <urn:r> <http://www.w3.org/1999/02/22-rdf-syntax-ns#reifies>
				  <<( <urn:s> <urn:p> <<( <urn:a> <urn:b> <urn:c> )>> )>> . }
				""";
		String configuration = "[] a parse:Source; parse:content ?doc; parse:format \"application/trig\" . ";
		String pattern = "?r rdf:reifies <<( ?s <urn:p> <<( ?a ?b ?c )>> )>> .";
		assertTrue(select("SELECT ?s WHERE { SERVICE <urn:rdf4j:parse> { " + configuration + pattern + " } }",
				document).isEmpty());
		var rows = select("SELECT ?g ?a ?c WHERE { SERVICE <urn:rdf4j:parse> { " + configuration
				+ " GRAPH ?g { " + pattern + " } } }", document);
		assertEquals(1, rows.size());
		assertEquals(VF.createIRI("urn:g"), rows.get(0).getValue("g"));
		assertEquals(VF.createIRI("urn:a"), rows.get(0).getValue("a"));
		assertEquals(VF.createIRI("urn:c"), rows.get(0).getValue("c"));
	}

